const inputs = $input.all();
const normalizeHeader = (value) => String(value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
function parseCSV(text) {
  if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
  const rows = []; let row = []; let field = ''; let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') quoted = false;
      else field += c;
    } else if (c === '"') quoted = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else if (c !== '\r') field += c;
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  if (quoted) throw new Error('CSV contains an unclosed quoted field');
  return rows;
}
function parseDate(value) {
  const match = String(value ?? '').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!match) return null;
  const month = Number(match[1]); const day = Number(match[2]); const year = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) return null;
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}
function parseAmount(value) {
  const normalized = String(value ?? '').trim().replace(/,/g, '');
  if (!normalized) return null;
  const amount = Number(normalized);
  return Number.isFinite(amount) ? amount : null;
}
const typeMap = { payout: 'payout', 'đặt phòng': 'booking', 'thuế khấu lưu': 'withholding_tax' };
const required = ['Loại', 'Mã xác nhận', 'Số tiền', 'Đã chi trả', 'Ngày chi trả', 'Mã tham chiếu'];
return inputs.map(({ json: input }) => {
  if (input.dry_run !== true) throw new Error('Safety guard: dry_run must be true');
  const csv = String(input.csv ?? '');
  if (Buffer.byteLength(csv, 'utf8') > 1024 * 1024) throw new Error('CSV exceeds the 1 MiB local Phase 1 limit');
  const rows = parseCSV(csv);
  if (rows.length < 2) throw new Error('CSV is empty');
  const header = rows[0].map(normalizeHeader);
  const missing = required.filter((name) => !header.includes(normalizeHeader(name)));
  if (missing.length) throw new Error(`Missing required columns: ${missing.join(', ')}`);
  const index = Object.fromEntries(header.map((name, position) => [name, position]));
  const valueAt = (row, name) => String(row[index[normalizeHeader(name)]] ?? '').trim();
  const records = []; const errors = [];
  rows.slice(1).forEach((row, offset) => {
    const line = offset + 2;
    if (row.length !== header.length) { errors.push({ line, code: 'invalid_column_count', expected: header.length, actual: row.length }); return; }
    const transactionType = typeMap[normalizeHeader(valueAt(row, 'Loại'))] ?? null;
    const payoutDate = parseDate(valueAt(row, 'Ngày chi trả'));
    const amount = parseAmount(valueAt(row, 'Số tiền'));
    const paidAmount = parseAmount(valueAt(row, 'Đã chi trả'));
    const confirmationCode = valueAt(row, 'Mã xác nhận') || null;
    const referenceCode = valueAt(row, 'Mã tham chiếu') || null;
    const rowErrors = [];
    if (!transactionType) rowErrors.push('unsupported_transaction_type');
    if (!payoutDate) rowErrors.push('invalid_payout_date');
    if (!referenceCode) rowErrors.push('missing_reference_code');
    if (transactionType === 'payout' && paidAmount === null) rowErrors.push('invalid_paid_amount');
    if (transactionType !== 'payout' && amount === null) rowErrors.push('invalid_amount');
    if (transactionType !== 'payout' && !confirmationCode) rowErrors.push('missing_confirmation_code');
    const startDateRaw = valueAt(row, 'Ngày bắt đầu'); const endDateRaw = valueAt(row, 'Ngày kết thúc');
    const startDate = startDateRaw ? parseDate(startDateRaw) : null; const endDate = endDateRaw ? parseDate(endDateRaw) : null;
    if (startDateRaw && !startDate) rowErrors.push('invalid_start_date');
    if (endDateRaw && !endDate) rowErrors.push('invalid_end_date');
    if (rowErrors.length) { errors.push({ line, codes: rowErrors }); return; }
    records.push({ line, transaction_type: transactionType, confirmation_code: confirmationCode, reference_code: referenceCode, payout_date: payoutDate, start_date: startDate, end_date: endDate, guest_name: valueAt(row, 'Khách') || null, listing_name: valueAt(row, 'Nhà/phòng cho thuê') || null, currency: valueAt(row, 'Loại tiền tệ') || null, amount, paid_amount: paidAmount });
  });
  const payouts = records.filter((record) => record.transaction_type === 'payout');
  const transactions = records.filter((record) => record.transaction_type !== 'payout');
  return { json: { dry_run: true, valid: errors.length === 0, source: input.source, row_count: rows.length - 1, normalized_count: records.length, payout_count: payouts.length, booking_count: transactions.filter((record) => record.transaction_type === 'booking').length, withholding_tax_count: transactions.filter((record) => record.transaction_type === 'withholding_tax').length, error_count: errors.length, errors, payouts, transactions, network_calls: 0, database_writes: 0 } };
});

const seenPayouts = new Set();
const seenTransactions = new Set();
return $input.all().map(({ json: input }) => {
  if (input.dry_run !== true) throw new Error('Safety guard: dry_run must be true');
  const payouts = input.payouts.map((payout) => {
    const idempotencyKey = JSON.stringify([payout.reference_code, payout.payout_date, payout.paid_amount]);
    const classification = seenPayouts.has(idempotencyKey) ? 'duplicate' : 'would_insert';
    seenPayouts.add(idempotencyKey);
    return { ...payout, idempotency_key: idempotencyKey, classification };
  });
  const transactions = input.transactions.map((transaction) => {
    const idempotencyKey = JSON.stringify([transaction.confirmation_code, transaction.payout_date, transaction.transaction_type, transaction.amount]);
    const classification = seenTransactions.has(idempotencyKey) ? 'duplicate' : 'would_insert';
    seenTransactions.add(idempotencyKey);
    return { ...transaction, idempotency_key: idempotencyKey, classification };
  });
  const all = [...payouts, ...transactions];
  return { json: { ...input, payouts, transactions, idempotency_preview: { scope: 'current_local_batch_only', would_insert: all.filter((record) => record.classification === 'would_insert').length, duplicate: all.filter((record) => record.classification === 'duplicate').length, would_update: 0, database_comparison_performed: false }, network_calls: 0, database_writes: 0 } };
});

const listingMap = { 'Villa Mẫu 1': '00000000-0000-4000-8000-000000000001', 'Villa Mẫu 2': '00000000-0000-4000-8000-000000000002' };
return $input.all().map(({ json: input }) => {
  if (input.dry_run !== true) throw new Error('Safety guard: dry_run must be true');
  const bookingListings = new Map();
  for (const transaction of input.transactions) {
    if (transaction.transaction_type !== 'booking') continue;
    const listingId = listingMap[transaction.listing_name] ?? null;
    if (listingId && transaction.confirmation_code) bookingListings.set(transaction.confirmation_code, listingId);
  }
  const transactions = input.transactions.map((transaction) => {
    const directListingId = transaction.listing_name ? listingMap[transaction.listing_name] ?? null : null;
    const inheritedListingId = transaction.confirmation_code ? bookingListings.get(transaction.confirmation_code) ?? null : null;
    const listingId = directListingId ?? inheritedListingId;
    const requiresListing = transaction.transaction_type === 'booking' || transaction.transaction_type === 'withholding_tax';
    const mappingStatus = !requiresListing ? 'not_applicable' : directListingId ? 'mapped' : inheritedListingId ? 'mapped_via_confirmation' : 'unmapped_listing';
    return { ...transaction, idempotency_classification: transaction.classification, classification: mappingStatus === 'unmapped_listing' ? 'unmapped_listing' : transaction.classification, listing_id: listingId, listing_mapping_status: mappingStatus };
  });
  const mapped = transactions.filter((record) => record.listing_mapping_status === 'mapped').length;
  const mappedViaConfirmation = transactions.filter((record) => record.listing_mapping_status === 'mapped_via_confirmation').length;
  const unmapped = transactions.filter((record) => record.listing_mapping_status === 'unmapped_listing').length;
  return { json: { ...input, transactions, listing_mapping_preview: { scope: 'redacted_local_fixture_only', mapped, mapped_via_confirmation: mappedViaConfirmation, unmapped_listing: unmapped, production_listing_lookup_performed: false }, network_calls: 0, database_writes: 0 } };
});
